# Extract Georgia data for years 2020-2029 (columns 50-59)
python3 << 'EOF'
import csv

# Read the file
with open('/tmp/weo_data.tsv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f, delimiter='\t')
    header = next(reader)

    # Find year columns (2020=col50, 2029=col59)
    year_cols = {}
    for i, h in enumerate(header):
        if h.strip() in [str(y) for y in range(2020, 2030)]:
            year_cols[h.strip()] = i

    print("Year columns:", year_cols)

    # Read Georgia data
    for row in reader:
        if len(row) > 2 and row[0].strip() == '915':
            code = row[2].strip()
            if code in ['NGDP_RPCH', 'NGDP', 'NGDPD', 'NGDP_D']:
                values = {}
                for year, col_idx in sorted(year_cols.items()):
                    if col_idx < len(row):
                        values[year] = row[col_idx].strip()
                print(f"\n{code} ({row[4].strip()}):")
                print(f"  Units: {row[6].strip()}, Scale: {row[7].strip()}")
                for year in sorted(values.keys()):
                    print(f"  {year}: {values[year]}")
EOF
